INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Butuh Gerakan Presisi, Bukan Sekadar Putaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Banyak proyek elektronik membutuhkan gerakan yang bisa diatur sudutnya dengan tepat: lengan robot, pintu otomatis, atau kemudi mobil RC. Motor DC biasa hanya bisa berputar terus, sehingga tidak cocok. Motor servo adalah jawabannya: motor kecil yang bisa diputar ke sudut tertentu (biasanya 0-180 derajat) dan berhenti di sana dengan presisi. Artikel ini memandu Anda memakai servo SG90 dengan Arduino dari nol.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Cara Kerja Motor Servo$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Motor servo berisi motor DC kecil, gearbox, potensiometer, dan rangkaian kontrol. Potensiometer membaca posisi poros saat ini; rangkaian membandingkannya dengan sinyal perintah berupa pulsa PWM yang dikirim setiap 20 ms. Lebar pulsa menentukan sudut: sekitar 1 ms untuk 0 derajat, 1,5 ms untuk 90 derajat, dan 2 ms untuk 180 derajat. Servo SG90 yang populer berdaya 5V dengan torsi sekitar 1,8 kg-cm, cukup untuk proyek ringan hingga menengah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat dan Bahan yang Diperlukan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Motor servo SG90 (atau MG996R untuk torsi lebih besar)$$, $$Papan Arduino Uno atau Nano$$, $$Kabel jumper male-to-female$$, $$Breadboard (opsional)$$, $$Catu daya eksternal 5V jika memakai beberapa servo$$, $$Kabel USB untuk upload program$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Rangkai, Program, dan Uji$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Rangkai kabel: cokelat = GND, merah = VCC 5V, kuning/oranye = sinyal ke pin D9 Arduino. Untuk satu servo daya dari Arduino cukup; untuk beberapa servo gunakan catu daya eksternal 5V dengan GND disamakan. Di Arduino IDE pilih Sketch > Include Library > Servo, buka File > Examples > Servo > Sweep, lalu upload: servo mengayun 0-180 derajat. Uji posisi dengan myservo.write(90). Untuk kendali manual, hubungkan potensiometer ke A0, petakan analogRead 0-1023 ke 0-180 dengan map(), dan beri delay 15 ms agar gerakan stabil.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Servo bergetar terus: beban terlalu berat atau catu daya kurang kuat$$, $$Servo panas: tegangan berlebih atau dipaksa menahan beban berat terus-menerus$$, $$Gerakan tidak akurat: kabel sinyal longgar atau GND tidak tersambung bersama$$, $$Jangan paksa memutar poros servo dengan tangan saat menyala, gigi plastik bisa patah$$, $$Untuk beban berat gunakan MG996R (torsi 10 kg-cm), bukan SG90$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Berhasil jika servo bergerak ke sudut yang diperintahkan (uji 0, 90, dan 180 derajat) dan berhenti tepat tanpa bergetar. Tindak lanjut: gabungkan dua servo menjadi lengan robot 2 sumbu, atau tambahkan sensor ultrasonik HC-SR04 untuk membuat pintu otomatis yang terbuka saat ada orang mendekat.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Sop Iga Amis, Keruh, dan Daging Keras$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Sop iga yang enak punya kuah bening berkilau, aroma rempah harum, dan daging iga empuk sampai lepas dari tulang. Masalah umum: kuah keruh keabu-abuan, bau amis, dan daging alot meski sudah lama direbus. Penyebabnya biasanya teknik merebus yang salah dan bumbu yang kurang seimbang. Dengan teknik rebus dua tahap, semua masalah itu teratasi.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Kunci Kuah Bening$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Kekeruhan kuah berasal dari protein dan kotoran darah yang keluar dari tulang saat mendidih. Teknik rebus dua tahap mengatasinya: rebusan pertama membuang semua kotoran, rebusan kedua menghasilkan kaldu murni yang bening. Bumbu rempah seperti pala, cengkeh, dan kayu manis memberi aroma khas sop iga ala restoran. Daging iga mengandung kolagen yang butuh 2-3 jam api kecil (atau 45 menit dengan panci presto) untuk empuk.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Bahan untuk 6 Porsi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$1 kg iga sapi, potong-potong$$, $$2,5 liter air$$, $$3 siung bawang putih geprek, 6 siung bawang merah iris$$, $$2 cm jahe geprek$$, $$1 batang kayu manis, 3 butir cengkeh, 1/2 butir pala$$, $$2 batang daun bawang, 2 batang seledri$$, $$2 buah wortel dan 2 buah kentang, potong$$, $$Garam, gula, merica, kaldu bubuk secukupnya, bawang goreng untuk taburan$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah 1: Rebus Pertama (Buang Kotoran)$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Didihkan air, masukkan iga, rebus 5-10 menit hingga busa kotor keabu-abuan muncul. Buang seluruh air rebusan dan bilas iga dengan air bersih. Langkah ini kunci kuah bening dan tidak boleh dilewatkan: merebus lama dalam air yang sama membuat kotoran menyatu ke kaldu dan kuah jadi keruh permanen.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Langkah 2: Rebus Kedua, Bumbui, dan Sajikan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Didihkan 2,5 liter air baru, masukkan iga yang sudah dibilas beserta bawang putih, bawang merah, jahe, kayu manis, cengkeh, dan pala. Masak dengan api kecil (simmer, bukan mendidih bergolak) 2-2,5 jam hingga daging empuk. Setelah empuk, masukkan wortel dan kentang, masak 15 menit. Bumbui dengan garam, gula, merica, dan kaldu bubuk; cicipi hingga gurih dengan aroma rempah lembut. Masukkan daun bawang dan seledri di akhir agar warnanya tetap segar. Sajikan panas dengan taburan bawang goreng, sambal, dan jeruk nipis.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Risiko, Kesalahan Umum, dan Penyimpanan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Kuah keruh: melewatkan rebus pertama atau api terlalu besar saat simmer$$, $$Bau amis: iga tidak dicuci bersih atau air rebusan pertama tidak dibuang$$, $$Daging alot: waktu rebus kurang atau api terlalu besar membuat serat mengkerut$$, $$Jangan tambah air dingin di tengah merebus; pakai air panas agar suhu stabil$$, $$Rempah berlebihan (terutama cengkeh) membuat kuah pahit$$, $$Sisa sop tahan 2-3 hari di kulkas atau 2 minggu di freezer; panaskan ulang dengan api kecil$$]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Unsur Kedua Terbanyak di Alam Semesta$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Helium (simbol He, nomor atom 2) adalah unsur kedua terbanyak di alam semesta setelah hidrogen, menyusun sekitar 24 persen massa materi biasa. Ia terbentuk beberapa menit setelah Big Bang dan terus diproduksi di inti bintang, termasuk Matahari, melalui fusi hidrogen. Meski melimpah di bintang, helium sangat langka di atmosfer Bumi karena terlalu ringan sehingga lepas ke luar angkasa.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Struktur Atom yang Sempurna Stabil$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Atom helium hanya punya 2 proton, 2 neutron, dan 2 elektron yang mengisi penuh kulit elektron pertama. Kulit penuh inilah yang membuatnya sangat stabil: ia tidak mau melepaskan atau menerima elektron dari atom lain. Helium termasuk gas mulia (golongan 18), kelompok unsur yang hampir tidak pernah membentuk senyawa kimia dalam kondisi normal.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Sifat Fisik yang Unik$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Helium adalah gas tidak berwarna, tidak berbau, tidak berasa, dan tidak beracun. Titik didihnya minus 268,9 derajat Celsius, terendah di antara semua unsur, sehingga helium cair adalah zat terdingin yang dikenal manusia. Massa jenisnya hanya sekitar 0,18 gram per liter, sehingga balon helium melayang di udara. Menghirupnya membuat suara melengking lucu karena bunyi merambat lebih cepat, tetapi berbahaya: helium menggantikan oksigen di paru-paru dan bisa menyebabkan pingsan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Manfaat: Dari Balon hingga Rumah Sakit$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Helium dipakai mengisi balon udara dan balon pesta karena ringan dan tidak mudah terbakar, berbeda dengan hidrogen yang meledak seperti tragedi Hindenburg 1937. Dalam dunia medis, helium cair mendinginkan magnet superkonduktor mesin MRI hingga suhu mendekati nol mutlak. Ia juga dipakai sebagai gas pelindung pengelasan, pendeteksi kebocoran, dan pendingin reaktor nuklir tertentu.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Fakta, Sumber, dan Kelangkaan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Namanya dari kata Yunani helios (Matahari): terdeteksi di spektrum Matahari tahun 1868 sebelum ditemukan di Bumi$$, $$Helium cair bersifat superfluida: mengalir tanpa gesekan dan merayap naik menembus dinding wadah$$, $$Kadarnya di atmosfer hanya sekitar 5 bagian per juta$$, $$Berasal dari peluruhan radioaktif uranium dan torium di kerak bumi; diekstraksi dari gas alam di AS, Qatar, Aljazair$$, $$Tidak mudah dibuat dan terus lepas ke angkasa: pakai hemat untuk kebutuhan penting seperti medis dan riset$$, $$Isotop helium-3 disebut bahan bakar impian reaktor fusi masa depan dan melimpah di permukaan Bulan$$]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Perang Termahal dalam Sejarah Kolonial Belanda$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Perang Diponegoro atau Perang Jawa (1825-1830) adalah perlawanan terbesar rakyat Indonesia terhadap penjajahan Belanda. Perang ini menelan biaya sekitar 20 juta gulden, membuat kas Belanda hampir bangkrut, dan menewaskan sekitar 200 ribu jiwa di pihak Jawa serta 15 ribu tentara Belanda. Perang ini mengubah total kebijakan kolonial Belanda di Nusantara.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Latar Belakang dan Strategi Gerilya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Pangeran Diponegoro, putra sulung Hamengkubuwono III yang hidup sederhana dan dekat rakyat, mengangkat senjata pada 20 Juli 1825 setelah Belanda memasang patok jalan melewati makam leluhurnya di Tegalrejo tanpa izin, ditambah pajak mencekik dan campur tangan Belanda dalam istana. Pasukannya tidak melawan terbuka melainkan memakai taktik gerilya: menyerang pos Belanda lalu menghilang ke hutan dan desa, didukung rakyat dan jaringan mata-mata. Perang ini didukung Kyai Mojo sebagai penasihat spiritual, Sentot Prawirodirdjo sebagai panglima, serta para bupati dan ulama. Di pihak Belanda, Jenderal De Kock membangun sistem benteng (benteng stelsel) untuk mempersempit ruang gerak gerilya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Titik Balik dan Penangkapan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Pada 1826-1827 pasukan Diponegoro menguasai sebagian besar Jawa Tengah dan mengepung Yogyakarta. Namun Belanda mendatangkan tentara dari luar Jawa dan membangun ratusan benteng kecil yang saling terhubung; kekalahan di beberapa pertempuran besar dan berkurangnya perbekalan melemahkan pasukan Diponegoro sejak 1828. Pada 28 Maret 1830, Diponegoro diundang berunding ke rumah Residen Kedu di Magelang lalu ditangkap secara licik, menandai berakhirnya Perang Jawa. Ia diasingkan ke Manado lalu Makassar, dan wafat di Benteng Rotterdam Makassar pada 8 Januari 1855.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Dampak dan Warisan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Biaya perang yang raksasa membuat Belanda memeras keuntungan lebih besar lewat Cultuurstelsel atau Sistem Tanam Paksa (1830-1870) gagasan Van den Bosch; ironisnya penderitaan itu memicu kritik di Belanda dan melahirkan politik etis. Diponegoro dikenang sebagai pahlawan nasional: namanya diabadikan pada universitas, jalan, dan Kodam IV/Diponegoro, dan Babad Diponegoro yang ditulisnya saat diasingkan menjadi sumber sejarah penting dari sudut pandang Jawa.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Fakta Menarik dan Pelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Melibatkan hampir seluruh Jawa Tengah dan sebagian Jawa Timur selama 5 tahun$$, $$Belanda sampai harus meminjam uang untuk membiayai perang ini$$, $$Sentot Prawirodirdjo akhirnya menyerah dan diangkat menjadi bupati$$, $$Perang ini menewaskan sekitar 200 ribu jiwa, terbesar di era kolonial$$, $$Pelajaran: penindasan ekonomi dan penghinaan martabat memicu perlawanan; persatuan ulama, bangsawan, dan rakyat nyaris mengalahkan mesin perang kolonial modern$$]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, siswa diharapkan mampu: (1) menjelaskan pengertian tenaga kerja, angkatan kerja, dan kesempatan kerja; (2) mengidentifikasi jenis-jenis pengangguran; (3) menganalisis penyebab dan dampak pengangguran; (4) menjelaskan upaya pemerintah mengatasi pengangguran.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Dasar Ketenagakerjaan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Tenaga kerja adalah setiap orang yang mampu melakukan pekerjaan untuk menghasilkan barang atau jasa. Angkatan kerja adalah penduduk usia kerja (15 tahun ke atas) yang bekerja atau sedang mencari pekerjaan. Bukan angkatan kerja adalah mereka yang bersekolah, mengurus rumah tangga, atau tidak mampu bekerja. Kesempatan kerja adalah lapangan pekerjaan yang tersedia bagi angkatan kerja.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Jenis-jenis Pengangguran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Pengangguran dibedakan menjadi: (1) terbuka, sama sekali tidak bekerja dan aktif mencari kerja; (2) terselubung, bekerja tetapi tidak sesuai kemampuan atau jam kerja minim; (3) musiman, terjadi pada musim tertentu seperti petani di luar musim tanam; (4) struktural, akibat perubahan struktur ekonomi misalnya otomatisasi; (5) friksional, terjadi saat berpindah pekerjaan; (6) siklikal, akibat lesunya perekonomian.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Penyebab, Dampak, dan Upaya Mengatasi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Penyebab pengangguran: pertumbuhan angkatan kerja lebih cepat dari lapangan kerja, ketidakcocokan keterampilan dengan kebutuhan industri, otomatisasi, krisis ekonomi, rendahnya kualitas pendidikan-pelatihan, dan informasi lowongan yang tidak merata. Dampaknya: pendapatan nasional dan daya beli turun, kemiskinan serta kriminalitas naik, kepercayaan diri individu merosot. Upaya pemerintah: pelatihan via Balai Latihan Kerja, mendorong investasi, mengembangkan UMKM dan kewirausahaan, memperbaiki pendidikan vokasi, program padat karya, dan penyaluran TKI resmi yang terlindungi.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Contoh Soal Terpecahkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Soal: Pabrik tekstil mengganti 200 pekerja dengan mesin otomatis. Jenis pengangguran apa yang terjadi dan bagaimana solusinya? Jawab: Ini pengangguran struktural akibat perubahan teknologi. Solusinya: pelatihan ulang (reskilling) agar pekerja menguasai keterampilan baru seperti operator mesin atau teknisi, serta program alih profesi ke sektor lain.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Soal 1: Jelaskan perbedaan angkatan kerja dan bukan angkatan kerja, berikan masing-masing 2 contoh! Kunci: angkatan kerja = penduduk usia 15+ yang bekerja/mencari kerja (karyawan, pencari kerja); bukan angkatan kerja = pelajar, ibu rumah tangga penuh waktu.$$, $$Soal 2: Sebutkan 4 jenis pengangguran beserta contohnya! Kunci: terbuka (lulusan baru belum dapat kerja), terselubung (sarjana jadi tukang parkir), musiman (petani di musim kemarau), struktural (kasir tergantikan mesin self-checkout).$$, $$Soal 3: Mengapa pengangguran struktural sulit diatasi dalam jangka pendek? Kunci: butuh perubahan keterampilan dan struktur ekonomi yang memakan waktu; pelatihan ulang, pendidikan, dan industri baru tidak bisa instan.$$]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah belajar materi ini, siswa diharapkan: (1) menjelaskan pengertian ibadah haji; (2) menyebutkan syarat wajib haji; (3) menyebutkan rukun dan wajib haji; (4) menjelaskan hikmah ibadah haji dalam kehidupan sehari-hari.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Ibadah Haji$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Haji adalah rukun Islam kelima, yaitu berkunjung ke Baitullah (Kakbah) di Makkah untuk melaksanakan ibadah tertentu pada waktu tertentu dengan syarat tertentu. Allah berfirman dalam QS Ali Imran ayat 97 bahwa mengerjakan haji adalah kewajiban manusia terhadap Allah bagi yang sanggup. Haji dilaksanakan pada bulan Zulhijah setiap tahun.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Syarat Wajib Haji$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Beragama Islam$$, $$Baligh (dewasa)$$, $$Berakal sehat$$, $$Merdeka$$, $$Mampu (istithaah): mampu biaya perjalanan, sehat jasmani, aman di perjalanan, dan keluarga yang ditinggal tercukupi$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Rukun dan Wajib Haji$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Rukun haji ada 6 dan tidak bisa diganti denda: (1) ihram, niat dengan pakaian ihram; (2) wukuf di Arafah pada 9 Zulhijah; (3) tawaf ifadah, mengelilingi Kakbah 7 kali; (4) sai antara Bukit Safa dan Marwah 7 kali; (5) tahalul, mencukur rambut; (6) tertib sesuai urutan. Wajib haji ada 5 dan bisa diganti dam jika ditinggalkan: (1) ihram dari miqat; (2) mabit di Muzdalifah; (3) mabit di Mina; (4) melempar jumrah ula, wusta, aqabah; (5) tawaf wada. Saat ihram ada larangan: memakai pakaian berjahit (laki-laki), wangi-wangian, mencukur rambut, memotong kuku, berburu, dan akad nikah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Hikmah Ibadah Haji$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Hikmah haji: melatih kesabaran dan keikhlasan; menumbuhkan persaudaraan karena jutaan muslim berkumpul tanpa membedakan bangsa; mengingatkan kesederhanaan lewat pakaian ihram yang sama; menghapus dosa bagi haji yang mabrur; melatih disiplin waktu dan aturan. Saat wukuf di Arafah, raja dan rakyat jelata memakai ihram putih yang sama dan tidak bisa dibedakan: di hadapan Allah semua manusia sama, yang membedakan hanyalah ketakwaan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Soal 1: Sebutkan 5 syarat wajib haji! Kunci: Islam, baligh, berakal sehat, merdeka, mampu (istithaah).$$, $$Soal 2: Jelaskan perbedaan rukun haji dan wajib haji beserta contohnya! Kunci: rukun tidak bisa diganti denda (contoh: wukuf di Arafah); wajib bisa diganti dam jika ditinggalkan (contoh: mabit di Muzdalifah).$$, $$Soal 3: Mengapa pakaian ihram berwarna putih dan tidak berjahit bagi laki-laki? Kunci: putih melambangkan kesucian dan kesederhanaan; tidak berjahit mengajarkan meninggalkan kemewahan dunia dan kesetaraan di hadapan Allah.$$]));
